<template><div class="page-card"><h2>读者管理</h2><div class="toolbar"><el-input v-model="keyword" placeholder="证号/姓名/账号" style="width:240px"/><el-button type="primary" @click="load">查询</el-button></div><el-table :data="rows"><el-table-column prop="readerNo" label="证号"/><el-table-column prop="username" label="账号"/><el-table-column prop="realName" label="姓名"/><el-table-column prop="phone" label="电话"/><el-table-column prop="status" label="状态"/></el-table><el-pagination layout="prev,pager,next" :total="total" v-model:current-page="page" @current-change="load"/></div></template>
<script setup>import {ref,onMounted} from 'vue';import http from '../api/http';const rows=ref([]),total=ref(0),page=ref(1),keyword=ref('');async function load(){const r=await http.get('/readers',{params:{page:page.value,size:10,keyword:keyword.value}});rows.value=r.data.records;total.value=r.data.total}onMounted(load)</script>
